func decodeToProof(p []string) [][]byte {
	var proofsBytes [][]byte
	for _, proof := range p {
		proofBytes, err := hex.DecodeString(proof)
		if err != nil {
			panic(err)
		}
		proofsBytes = append(proofsBytes, proofBytes)
	}
	return proofsBytes
}

func TestAdjustableBlock(t *testing.T) {
	adjustableData := &AdjustmentData{
		BuilderAddress:      common.HexToAddress("0x65b84d3dd25d4ae7fd511917d8691ba22fbb00a7"),
		FeeRecipientAddress: common.HexToAddress("0x8e109f7d973bcc09a38b1d67223a5a38d30febee"),
		FeePayerAddress:     common.HexToAddress("0x6eebc39f68eb30f84f7c2efd8b0164dbb6fe6a01"),
		BuilderProof:        decodeToProof([]string{"", "f871a03798095a47d6d8e2ae6c37a13814d3f51a6b8fd1da64ef511eb6e158d2abf401b84ef84c01880de0b6b3a6cb1778a056e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421a0c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470"}),
		FeeRecipientProof:   decodeToProof([]string{"", "f8518080808080808080a0af4ad9ff9b81a794813daf3d9722eb59df02b3791fac597eff611ccf9740a2ec80a062b340cbb8f543cbcca85ac5f553489e055566bfbc7c289929a37106649354eb808080808080", "f871a0208f0fa0321c3de6c0f10b3240502577a4e5f50aba5901f709a2ec3873dbe076b84ef84c80880de0b6b3a848e1c0a056e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421a0c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470"}),

		FeePayerProof: decodeToProof([]string{"", "f871a03592aa337753e35a661bb6351f13f5d91954147fb8bc4977d27e2f1eda725254b84ef84c80880de0b6b3a7640000a056e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421a0c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470"}),

		PlaceholderTxProof:      decodeToProof([]string{"f871a0c0b70f674a42dd6c4577a8a1d3ad484a946a2fc132a4112ae6f664a9daf5d99aa00d1c17b0ff96143a25bf57765d6564720a6f4cb85b79b1d698d7279a88d6de3ca098185a91af95a5363378f66c5c1925ae9aa74b04cd18ce7284be75e28e73f28e8080808080808080808080808080", "", "f86d20b86a02f867820539808001825208948e109f7d973bcc09a38b1d67223a5a38d30febee8398968080c080a0783a287962998a3a67b1ce11a078320dfe3036b9ea0363e2630d7d3ccb596bbda01296f5b981da62f675e248aeaee075146136862be917e5a65b3cf0ca02e04ec1"}),
		PlaceholderReceiptProof: decodeToProof([]string{"f871a0146028410ee4f6681e17378b3b785764b02e13e64eeeaabf7c22c0786a398527a04f4d6ae8caaaa1698956b3acebc3f2ac0a0b48606516abdb900feb872822eacfa0bfd07fcbe64496f5517c0314e9d4059712842e054de7b6caa1a2ad26b6145fdb8080808080808080808080808080", "", ""}),
		StateRoot:               common.HexToHash("0x54ec72078c12ac8adf1805022c76aae18245eb6b2d0df5f45e7972258b12bdc5"),
		TransactionsRoot:        common.HexToHash("0x565fb412106ac54391761482b3c6cf0b327c31be125961956a54109084f2b378"),
		ReceiptsRoot:            common.HexToHash("0x8fbd2e1bf61b9d9923a99cfb327625b1818268f0e3a9a03eabb1d3a9c7d9727c"),
	}
	expectedStateRoot := common.HexToHash("0x0cf6dc8ff8a2d522053b2419053a3b886c4736735dc10f311ee76944e383ccc3")
	expectedTxRoot := common.HexToHash("0x3e70e4e24e2eadcf59550aa928d7e5b56cc2e019c5d74300f480059c6b9207fe")
	expectedReceiptRoot := common.HexToHash("0x8fbd2e1bf61b9d9923a99cfb327625b1818268f0e3a9a03eabb1d3a9c7d9727c")

	lastTxBytes, err := hex.DecodeString("02f867820539808001825208948e109f7d973bcc09a38b1d67223a5a38d30febee8307a12080c001a04753e4043f1d30875686e6309cf59376a324e1f1b9493e8999fa0d2237985a2ba008ebb986b32f40cec32063be678f17be909b6ff8e2ffbc07fc9703d9ccf25fbd")
	require.NoError(t, err)
	tx := new(types.Transaction)
	err = tx.UnmarshalBinary(lastTxBytes)
	require.NoError(t, err)
	fmt.Println(tx.Value().String())
	for _, h := range adjustableData.BuilderProof {
		fmt.Println("hash", hex.EncodeToString(h))
	}
	// fmt.Println("Builder State Proof", adjustableData.BuilderProof)
	var TestLog = zerolog.New(zerolog.ConsoleWriter{Out: os.Stdout, TimeFormat: "2006-01-02T15:04:05.000Z07:00"}).With().Timestamp().Logger()

	rootNode, builderState, feeRecipientState, payerState, err := GetStateValueNodes(
		adjustableData.BuilderAddress,
		adjustableData.BuilderProof,
		adjustableData.FeeRecipientAddress,
		adjustableData.FeeRecipientProof,
		adjustableData.FeePayerAddress,
		adjustableData.FeePayerProof,
		adjustableData.StateRoot,
	)
	require.NoError(t, err)

	stateRoot, txRoot, receiptRoot, err := AdjustBlock(
		AdjustmentDataV1ToVersioned(adjustableData),
		adjustableData.TransactionsRoot,
		adjustableData.ReceiptsRoot,
		1,
		21000,
		10000000,
		10000000,
		500000,
		uint64(51),
		tx,
		&TestLog,
		true,
		nil,
		rootNode,
		builderState,
		feeRecipientState,
		payerState,
	)

	require.NoError(t, err)
	require.Equal(t, expectedStateRoot, stateRoot)
	require.Equal(t, expectedTxRoot, txRoot)
	require.Equal(t, expectedReceiptRoot, receiptRoot)
}

func TestGetTxValueNodes(t *testing.T) {
	numTxs := uint64(28)
	elTransactionsRoot := common.HexToHash("0x36e997d0d45f16daf83f636f2308803a4a20736f1669fcb4410eabb786589532")
	elPlaceholderTxProof := []string{
		"f871a07fe0b308e4ed22dd54dfd310190c1a174de8645e4769649435c3f9061f6eced2a0bf3265e6c7293ae38b4a9b17dca3f1333f18d8f4047a63eb93b9172c1ad2bae2808080808080a014868518eaf3c9b7c6f59cccf3349c484ec4a38286fee43c37f805cbcc2f2f278080808080808080",
		"",
		"f87820b87502f87283088bb0826686808440db1b6e825208949029c772dde847622df1553ed9d9bdb7812e4f938723a9efee49bf1180c080a0efb043f9753b6fadab5db1294142ee47c0171b29986f8ac7522b9600aff976c6a06da16e8a9d93a0d788411cfbeda4862c97ed7b9f45bda46957fc61a8e8807e67",
	}

	// Recreate original payment tx from execution layer TransactionsRoot and Proof
	_, tx, err := GetTxValueNodes(numTxs-1, decodeToProof(elPlaceholderTxProof), elTransactionsRoot)

	require.NoError(t, err)
	require.Equal(t, uint8(2), tx.Type())
	require.Equal(t, common.HexToHash("0x520a06faad1a06605ea9e5aba8217f1997719e1f5acaa88da16578afcf6bc6e7"), tx.Hash())
	require.Equal(t, uint64(26246), tx.Nonce())
	require.Equal(t, big.NewInt(10038472144961297), tx.Value())
	require.Equal(t, uint64(21000), tx.Gas())
	require.Equal(t, big.NewInt(1088101230), tx.GasPrice())
	require.Equal(t, big.NewInt(1088101230), tx.GasFeeCap())
	require.Equal(t, big.NewInt(0), tx.GasTipCap())
}
